{
 "ExteriorEnabled": false,
 "ExteriorQuality": 1,
 "InteriorEnabled": true,
 "InteriorQuality": 1,
 "_metadata": {
  "modName": "Argonia",
  "version": "1.15",
  "enabled": true,
  "description": "Round 5 ruling (2026-11-03, the sky bisect on Paris): this feature is OFF (neutered) until it is authored within measured bounds: with it and the volumetric lighting on, the sky was a grey veil with no clouds and dawn a cream wash; with both off the clouds returned and the dawn cast went grey; a residual grey from another Community Shaders feature remains to bisect. God rays and light shafts through canopy haze (vibe-01, vibe-06). Medium quality, not High: the quality is the 3D scattering texture size (High is 320x192x90 froxels), so Medium keeps the cost flat while shafts still show; raise only if the dawn stills show banding"
 }
}

{
 "Opacity": 0.5,
 "_metadata": {
  "modName": "Argonia",
  "version": "1.15",
  "enabled": true,
  "description": "Cloud shadows drifting over the marsh at the CS default 0.5 (range 0-4; higher is darker): moving dapple at vanilla-range contrast, one texture sample per pixel so no cost cliff; kept explicit so a stack change cannot darken it"
 }
}

{
 "EnableTerrainShadow": true,
 "_metadata": {
  "modName": "Argonia",
  "version": "1.15",
  "enabled": true,
  "description": "Long hill shadows at dawn and dusk (montane haze belt). It reads a baked height map per worldspace (textures/heightmaps) and does nothing where none exists, so it costs nothing in the marsh until Argonia ships a height map of its own; no tunable beyond on/off in 1.9.1"
 }
}

{
 "Glossiness": 20.0,
 "SpecularStrength": 0.3,
 "SubsurfaceScatteringAmount": 1.0,
 "_metadata": {
  "modName": "Argonia",
  "version": "1.15",
  "enabled": true,
  "description": "Backlit grass and reed glow so shafts land on a living ground: SSS amount 1.0 (CS default) and glossiness 20 (default), specular strength 0.3 under the 0.5 default so wet marsh grass does not glitter; pixel-shader terms only, no extra pass"
 }
}

